package com.threatstream.detection;
import java.time.Instant; import java.util.*; import org.springframework.stereotype.Component;
@Component class SuspiciousLoginRule implements DetectionRule { private final DetectionProperties p; private final AlertFactory f; private final Map<String,Deque<Instant>> failures=new HashMap<>(); SuspiciousLoginRule(DetectionProperties p,AlertFactory f){this.p=p;this.f=f;}
 public synchronized Optional<SecurityAlert> evaluate(AuthEvent e){ Deque<Instant> q=failures.computeIfAbsent(e.sourceIp(),x->new ArrayDeque<>()); Instant cut=e.timestamp().minus(p.suspiciousLogin().window()); while(!q.isEmpty()&&q.peek().isBefore(cut))q.remove(); if("FAILURE".equals(e.outcome())){q.add(e.timestamp());return Optional.empty();} if("SUCCESS".equals(e.outcome())&&q.size()>=p.suspiciousLogin().threshold()){var a=Optional.of(f.create("AUTH_FAILURES_THEN_SUCCESS","SUSPICIOUS_LOGIN_SEQUENCE","MEDIUM",e,q.size(),q.peek()));q.clear();return a;} return Optional.empty(); } }
